import{_ as n,C as o,o as e,c as s,a2 as l,b as i,w as a,a as d,E as g,a3 as E}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",f=JSON.parse('{"title":"납부 내역 관리","description":"","frontmatter":{},"headers":[],"relativePath":"payment/index.md","filePath":"payment/index.md","lastUpdated":1793459614000}'),B={name:"payment/index.md"};function C(h,t,c,_,u,x){const r=o("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="납부-내역-관리" tabindex="-1">납부 내역 관리 <a class="header-anchor" href="#납부-내역-관리" aria-label="Permalink to &quot;납부 내역 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="프로젝트 전체 대금 수납 현황 및 매칭 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/index.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>납부 내역 관리</strong> 페이지는 회사의 은행 통장(수납 계좌)에 입금된 분양 대금 내역을 총괄 조회하고, 각 입금 건을 실제 수분양자의 계약 건 및 납부 회차(계약금, 중도금, 잔금 등)에 정확하게 연결(매칭)하는 대금 수납의 중앙 통제 센터입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [대금 수납 관리] → [납부 내역 관리]**를 선택하여 접속합니다.</li></ul>',4)),(e(),i(E,null,{default:a(()=>[g(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%8F%A6%20%EC%9D%80%ED%96%89%20%ED%86%B5%EC%9E%A5%20%EC%9E%85%EA%B8%88%3Cbr%3E(%ED%9A%8C%EA%B3%84%20%EA%B1%B0%EB%9E%98%20%EC%9B%90%EC%9E%A5%20%EB%B0%98%EC%98%81)%22%5D%20--%3E%20B%5B%22%F0%9F%94%8D%20%EB%AF%B8%EB%93%B1%EB%A1%9D%20%EC%9E%85%EA%B8%88%20%EA%B1%B4%20%EC%8B%9D%EB%B3%84%3Cbr%3E(%EC%9E%85%EA%B8%88%EC%9E%90%EB%AA%85%C2%B7%EC%A0%81%EC%9A%94%C2%B7%EA%B8%88%EC%95%A1%20%EB%8C%80%EC%A1%B0)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%94%97%20%EA%B3%84%EC%95%BD%EC%9E%90%20%26%20%ED%9A%8C%EC%B0%A8%20%EB%A7%A4%EC%B9%AD%3Cbr%3E(%EB%8F%99%ED%98%B8%EC%88%98%20%EC%A7%80%EC%A0%95%20%EB%B0%8F%20%EB%B6%84%ED%95%A0%20%EB%B0%B0%EC%A0%95)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8A%20%EC%88%98%EB%82%A9%20%EC%8B%A4%EC%A0%81%20%26%20%EC%9E%94%EC%95%A1%20%EC%A7%91%EA%B3%84%3Cbr%3E(%EB%AF%B8%EB%82%A9%EC%95%A1%20%EC%9E%90%EB%8F%99%20%EC%B0%A8%EA%B0%90%C2%B7%EC%98%81%EC%88%98%EC%A6%9D%20%EB%B0%9C%EA%B8%89)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-수납-매칭-프로세스" tabindex="-1">1. 개요 및 수납 매칭 프로세스 <a class="header-anchor" href="#_1-개요-및-수납-매칭-프로세스" aria-label="Permalink to &quot;1. 개요 및 수납 매칭 프로세스&quot;">​</a></h2><p>회계 장부(원장)에 기록된 입금 내역을 바탕으로 평형 타입별 수납 요약 지표를 확인하고, 각 입금 건별로 어떤 계약자의 몇 회차 납부금인지 연결(매칭)합니다.</p><ul><li><strong>계약 미등록 건(불명금) 관리</strong>: 가족 명의로 입금되었거나 동명이인, 오입금으로 인해 계약자가 즉시 식별되지 않은 입금 내역을 별도 필터링하여 수동 매칭합니다.</li><li><strong>회차 미지정 건 관리</strong>: 계약자는 확인되었으나 계약금인지 중도금인지 회차가 정해지지 않은 건을 확인하여 해당 회차로 배정합니다.</li><li><strong>매출 목표 대비 실시간 수납률 분석</strong>: 최초 수입 예산 대비 현재 계약액과 실수납액, 미수금 현황을 한눈에 조망합니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>타입별 매출 예산 대비 분양 및 수납 현황 요약 제공</strong>: 목표액, 분양금액, 실수납액, 미수금, 미분양 잔여액 실시간 집계</li><li><strong>다차원 입금 내역 검색</strong>: 입금 일자, 수납 은행 계좌, 차수/타입, 납부 회차 등 다양한 조건 검색</li><li><strong>계약 미등록 및 회차 미지정 건 선별 매칭</strong>: 스위치 토글을 통해 확인이 필요한 미완료 수납 건만 집중 선별</li><li><strong>수납 건별 / 계약자별 엑셀 다운로드</strong>: 개별 거래 단위 또는 계약자별 누적 수납 현황 엑셀 추출</li><li><strong>원클릭 상세 이동</strong>: 매칭 완료된 수납 건 클릭 시 해당 계약자의 <a href="/payment/manage.html">건별 납부 관리</a> 화면으로 즉시 이동</li></ul><h2 id="_3-화면-구성-및-조작-가이드" tabindex="-1">3. 화면 구성 및 조작 가이드 <a class="header-anchor" href="#_3-화면-구성-및-조작-가이드" aria-label="Permalink to &quot;3. 화면 구성 및 조작 가이드&quot;">​</a></h2><h3 id="_1-상단-납부-현황-요약-카드" tabindex="-1">1. 상단 납부 현황 요약 카드 <a class="header-anchor" href="#_1-상단-납부-현황-요약-카드" aria-label="Permalink to &quot;1. 상단 납부 현황 요약 카드&quot;">​</a></h3><p>프로젝트의 전체 매출 목표 대비 실제 분양 및 수납 성과를 타입별로 집계하여 보여줍니다.</p><ul><li><strong>총 매출예산 (A)</strong>: <a href="/project/budgets.html">수입 예산 등록</a>에서 수립한 전체 분양 수입 목표액</li><li><strong>총 분양금액 (B)</strong>: 현재까지 체결된 모든 유효 계약의 총 공급가 합계</li><li><strong>총 수납금액 (C)</strong>: 실제로 통장에 입금 처리 완료된 금액의 합계</li><li><strong>미 수납금액 (B - C)</strong>: 계약은 체결되었으나 아직 입금되지 않고 남아있는 잔여 수납액</li><li><strong>미 분양금액 (A - B)</strong>: 매출 예산 중 아직 계약 체결되지 않은 잔여 목표액</li></ul><h3 id="_2-목록-제어-및-검색-툴바" tabindex="-1">2. 목록 제어 및 검색 툴바 <a class="header-anchor" href="#_2-목록-제어-및-검색-툴바" aria-label="Permalink to &quot;2. 목록 제어 및 검색 툴바&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">필터 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>납부일자 (From ~ To)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">특정 기간 내 입금된 거래 내역 필터링</td></tr><tr><td style="text-align:left;"><strong>차수 / 타입</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">특정 계약 그룹이나 평형 타입별 입금 내역 조회</td></tr><tr><td style="text-align:left;"><strong>납부회차 선택</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">계약금, 중도금, 잔금 등 특정 회차로 배정된 내역 조회</td></tr><tr><td style="text-align:left;"><strong>납부계좌 선택</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">특정 분양 수납 전용 계좌(신탁사 계좌 등)로 입금된 내역 조회</td></tr><tr><td style="text-align:left;"><strong>계약 미등록 (토글)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">통장에는 입금되었으나 아직 계약자와 연결되지 않은 건만 선별</td></tr><tr><td style="text-align:left;"><strong>회차 미등록 (토글)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">계약자는 연결되었으나 납부 회차가 미지정된 건만 선별</td></tr><tr><td style="text-align:left;"><strong>통합 검색창</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">계약자 성명, 입금자명, 통장 적요, 비고 키워드 검색</td></tr></tbody></table><h3 id="_3-대금-납부-현황-목록-그리드" tabindex="-1">3. 대금 납부 현황 목록 그리드 <a class="header-anchor" href="#_3-대금-납부-현황-목록-그리드" aria-label="Permalink to &quot;3. 대금 납부 현황 목록 그리드&quot;">​</a></h3><p>필터링된 수납 내역을 리스트 형태로 표출하며, 각 건의 매칭 상태를 시각적으로 보여줍니다:</p><ul><li><strong>노란색 배경 행</strong>: 계약 정보가 아직 연결되지 않은 수납 건 (계약자 매칭 필요)</li><li><strong>빨간색 텍스트</strong>: 계약자는 확인되었으나 납입 회차가 지정되지 않은 건 (회차 배정 필요)</li><li><strong>[확인 / 매칭] 버튼</strong>: 계약 미등록 건의 버튼을 클릭하여 수동으로 계약자를 검색하고 연결 처리</li></ul><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 가족 명의 입금(불명금) 매칭 요령</strong>: <ul><li>계약자 본인이 아닌 배우자나 자녀 명의로 대금이 입금된 경우, 시스템은 자동으로 &#39;계약 미등록(노란색 배경)&#39;으로 분류합니다.</li><li>상단 필터에서 <strong>[계약 미등록] 스위치</strong>를 켜서 불명금 목록을 조회한 뒤, 통장 적요란의 메모나 입금 금액을 단서로 계약자를 찾아 <strong><code>[확인]</code></strong> 버튼을 눌러 올바른 수분양자에게 매칭하십시오.</li></ul></li><li><strong>💡 수납 내역 엑셀 다운로드 활용</strong>: <ul><li><strong>수납건별 다운로드</strong>: 회계팀과 통장 입금 내역을 1:1로 대조(은행 거래 대사)할 때 사용합니다.</li><li><strong>계약자별 다운로드</strong>: 분양 시행사나 신탁사에 특정 시점까지의 &quot;수분양자별 누적 수납 총괄표&quot;를 공식 보고할 때 사용합니다.</li></ul></li></ul>',16))])}const p=n(B,[["render",C]]);export{f as __pageData,p as default};
